commands.command:
cat > /etc/nginx/conf.d/https-8443.conf <<'EOF'
server {
    listen 8443 ssl;
    listen [::]:8443 ssl;
    server_name node1.cert-rotation.local;

    ssl_certificate     /etc/nginx/tls/server.crt;
    ssl_certificate_key /etc/nginx/tls/server.key;

    location / {
        default_type text/plain;
        return 200 "ok\n";
    }
}
EOF
nginx -t 2>&1
